"""Private uploads and on-demand malware scanning; no mail submission permission."""
from infrastructure import ref, arn, sub


def template():
    retain = {'DeletionPolicy': 'Retain', 'UpdateReplacePolicy': 'Retain'}
    bucket = sub('ieosuia-email-files-${AWS::AccountId}-${AWS::Region}')
    root = sub('arn:${AWS::Partition}:s3:::ieosuia-email-files-${AWS::AccountId}-${AWS::Region}')
    q = sub('arn:${AWS::Partition}:s3:::ieosuia-email-files-${AWS::AccountId}-${AWS::Region}/quarantine/*')
    clean = sub('arn:${AWS::Partition}:s3:::ieosuia-email-files-${AWS::AccountId}-${AWS::Region}/clean/*')
    managed_rule = sub('arn:${AWS::Partition}:events:${AWS::Region}:${AWS::AccountId}:rule/DO-NOT-DELETE-AmazonGuardDutyMalwareProtectionS3*')
    policy = lambda statements: {'Version': '2012-10-17', 'Statement': statements}
    allow = lambda actions, resource, **kw: {'Effect': 'Allow', 'Action': actions, 'Resource': resource, **kw}
    trust = lambda service: policy([{'Effect': 'Allow', 'Principal': {'Service': service}, 'Action': 'sts:AssumeRole'}])
    r = {}
    r['Files'] = {'Type': 'AWS::S3::Bucket', **retain, 'Properties': {'BucketName': bucket, 'VersioningConfiguration': {'Status': 'Enabled'}, 'BucketEncryption': {'ServerSideEncryptionConfiguration': [{'ServerSideEncryptionByDefault': {'SSEAlgorithm': 'AES256'}}]}, 'PublicAccessBlockConfiguration': {k: True for k in ['BlockPublicAcls', 'IgnorePublicAcls', 'BlockPublicPolicy', 'RestrictPublicBuckets']}, 'OwnershipControls': {'Rules': [{'ObjectOwnership': 'BucketOwnerEnforced'}]}, 'NotificationConfiguration': {'EventBridgeConfiguration': {'EventBridgeEnabled': True}}, 'CorsConfiguration': {'CorsRules': [{'AllowedOrigins': ['https://sms.ieosuia.com'], 'AllowedMethods': ['PUT', 'GET', 'HEAD'], 'AllowedHeaders': ['content-type', 'x-amz-checksum-sha256', 'if-none-match'], 'ExposedHeaders': ['etag'], 'MaxAge': 300}]}, 'LifecycleConfiguration': {'Rules': [{'Id': 'QuarantineSevenDays', 'Status': 'Enabled', 'Prefix': 'quarantine/', 'ExpirationInDays': 7, 'NoncurrentVersionExpiration': {'NoncurrentDays': 1}, 'AbortIncompleteMultipartUpload': {'DaysAfterInitiation': 1}}, {'Id': 'CleanNinetyDays', 'Status': 'Enabled', 'Prefix': 'clean/', 'ExpirationInDays': 90, 'NoncurrentVersionExpiration': {'NoncurrentDays': 1}}, {'Id': 'ValidationCleanup', 'Status': 'Enabled', 'Prefix': 'malware-protection-resource-validation-object', 'ExpirationInDays': 1}]}}}
    r['FilesPolicy'] = {'Type': 'AWS::S3::BucketPolicy', 'Properties': {'Bucket': ref('Files'), 'PolicyDocument': policy([{'Effect': 'Deny', 'Principal': '*', 'Action': 's3:*', 'Resource': [root, sub('${Files.Arn}/*')], 'Condition': {'Bool': {'aws:SecureTransport': 'false'}}}, {'Effect': 'Deny', 'Principal': '*', 'Action': 's3:PutObject', 'Resource': [q, clean], 'Condition': {'Null': {'s3:if-none-match': 'true'}}}])}}
    scan_permissions = [allow(['events:PutRule', 'events:DeleteRule', 'events:PutTargets', 'events:RemoveTargets'], managed_rule, Condition={'StringLike': {'events:ManagedBy': 'malware-protection-plan.guardduty.amazonaws.com'}}), allow(['events:DescribeRule', 'events:ListTargetsByRule'], managed_rule), allow(['s3:GetObject', 's3:GetObjectVersion', 's3:GetObjectTagging', 's3:PutObjectTagging', 's3:GetObjectVersionTagging', 's3:PutObjectVersionTagging'], q), allow(['s3:PutBucketNotification', 's3:GetBucketNotification', 's3:ListBucket'], root), allow('s3:PutObject', sub('${Files.Arn}/malware-protection-resource-validation-object'))]
    r['ScanRole'] = {'Type': 'AWS::IAM::Role', 'Properties': {'AssumeRolePolicyDocument': trust('malware-protection-plan.guardduty.amazonaws.com'), 'Policies': [{'PolicyName': 'ScanOnlyQuarantinedCampaignFiles', 'PolicyDocument': policy(scan_permissions)}]}}
    r['ScanPlan'] = {'Type': 'AWS::GuardDuty::MalwareProtectionPlan', 'DependsOn': ['FilesPolicy', 'ScanRole'], 'Properties': {'Role': arn('ScanRole'), 'ProtectedResource': {'S3Bucket': {'BucketName': ref('Files'), 'ObjectPrefixes': ['quarantine/']}}, 'Actions': {'Tagging': {'Status': 'ENABLED'}}}}
    r['DeadLetters'] = {'Type': 'AWS::SQS::Queue', **retain, 'Properties': {'QueueName': 'ieosuia-email-file-scan-dead-v1', 'SqsManagedSseEnabled': True, 'MessageRetentionPeriod': 1209600}}
    state = sub('arn:${AWS::Partition}:dynamodb:${AWS::Region}:${AWS::AccountId}:table/${StateTable}')
    inspect_permissions = [allow(['dynamodb:GetItem', 'dynamodb:Query'], state), allow(['dynamodb:PutItem', 'dynamodb:DeleteItem', 'dynamodb:ConditionCheckItem'], state, Condition={'StringEquals': {'dynamodb:EnclosingOperation': 'TransactWriteItems'}}), allow('s3:GetObjectVersion', q), allow(['s3:PutObject', 's3:GetObject'], clean), allow('sqs:SendMessage', arn('DeadLetters')), allow(['logs:CreateLogStream', 'logs:PutLogEvents'], sub('arn:${AWS::Partition}:logs:${AWS::Region}:${AWS::AccountId}:log-group:/aws/lambda/ieosuia-email-file-scan-v1:*'))]
    r['InspectRole'] = {'Type': 'AWS::IAM::Role', 'Properties': {'AssumeRolePolicyDocument': trust('lambda.amazonaws.com'), 'Policies': [{'PolicyName': 'InspectExactQuarantinedFileVersions', 'PolicyDocument': policy(inspect_permissions)}]}}
    r['InspectLogs'] = {'Type': 'AWS::Logs::LogGroup', **retain, 'Properties': {'LogGroupName': '/aws/lambda/ieosuia-email-file-scan-v1', 'RetentionInDays': 14}}
    r['InspectFunction'] = {'Type': 'AWS::Lambda::Function', 'DependsOn': 'InspectLogs', 'Properties': {'FunctionName': 'ieosuia-email-file-scan-v1', 'Runtime': 'python3.13', 'Handler': 'handler.asset_scan', 'Role': arn('InspectRole'), 'Code': {'S3Bucket': ref('CodeBucket'), 'S3Key': ref('CodeKey')}, 'MemorySize': 512, 'Timeout': 60, 'DeadLetterConfig': {'TargetArn': arn('DeadLetters')}, 'Environment': {'Variables': {'STATE_TABLE': ref('StateTable'), 'AWS_ACCOUNT_ID': ref('AWS::AccountId'), 'ASSET_BUCKET': ref('Files'), 'SCAN_PLAN_ARN': arn('ScanPlan')}}}}
    r['RetryPolicy'] = {'Type': 'AWS::Lambda::EventInvokeConfig', 'Properties': {'FunctionName': ref('InspectFunction'), 'Qualifier': '$LATEST', 'MaximumRetryAttempts': 1, 'MaximumEventAgeInSeconds': 3600}}
    r['Results'] = {'Type': 'AWS::Events::Rule', 'Properties': {'Name': 'ieosuia-email-file-scan-results-v1', 'State': 'ENABLED', 'EventPattern': {'source': ['aws.guardduty'], 'detail-type': ['GuardDuty Malware Protection Object Scan Result'], 'account': [ref('AWS::AccountId')], 'region': [ref('AWS::Region')], 'resources': [arn('ScanPlan')], 'detail': {'s3ObjectDetails': {'bucketName': [ref('Files')]}}}, 'Targets': [{'Arn': arn('InspectFunction'), 'Id': 'InspectCleanVersion', 'RetryPolicy': {'MaximumRetryAttempts': 2, 'MaximumEventAgeInSeconds': 3600}, 'DeadLetterConfig': {'Arn': arn('DeadLetters')}}]}}
    r['ResultsPermission'] = {'Type': 'AWS::Lambda::Permission', 'Properties': {'FunctionName': ref('InspectFunction'), 'Action': 'lambda:InvokeFunction', 'Principal': 'events.amazonaws.com', 'SourceArn': arn('Results'), 'SourceAccount': ref('AWS::AccountId')}}
    r['DeadLetterPolicy'] = {'Type': 'AWS::SQS::QueuePolicy', 'Properties': {'Queues': [ref('DeadLetters')], 'PolicyDocument': policy([{'Effect': 'Allow', 'Principal': {'Service': 'events.amazonaws.com'}, 'Action': 'sqs:SendMessage', 'Resource': arn('DeadLetters'), 'Condition': {'ArnEquals': {'aws:SourceArn': arn('Results')}, 'StringEquals': {'aws:SourceAccount': ref('AWS::AccountId')}}}])}}
    for name, role, permissions in [('Api', 'ApiRoleName', [allow('s3:PutObject', q), allow('s3:GetObjectVersion', clean)]), ('Worker', 'WorkerRoleName', [allow('s3:GetObjectVersion', clean)])]:
        r[name + 'FilesPolicy'] = {'Type': 'AWS::IAM::Policy', 'Properties': {'PolicyName': 'OnlyImmutableCampaignFileVersions', 'Roles': [ref(role)], 'PolicyDocument': policy(permissions)}}
    r['DeadLetterAlarm'] = {'Type': 'AWS::CloudWatch::Alarm', 'Properties': {'AlarmDescription': 'Retained file inspection failures require review; uploads remain quarantined.', 'Namespace': 'AWS/SQS', 'MetricName': 'ApproximateNumberOfMessagesVisible', 'Dimensions': [{'Name': 'QueueName', 'Value': {'Fn::GetAtt': ['DeadLetters', 'QueueName']}}], 'Statistic': 'Maximum', 'Period': 300, 'EvaluationPeriods': 1, 'Threshold': 0, 'ComparisonOperator': 'GreaterThanThreshold', 'TreatMissingData': 'notBreaching'}}
    return {'AWSTemplateFormatVersion': '2010-09-09', 'Description': 'IEOSUIA private bounded email files with quarantine and usage-based malware scanning.', 'Parameters': {k: {'Type': 'String'} for k in ['CodeBucket', 'CodeKey', 'StateTable', 'ApiRoleName', 'WorkerRoleName']}, 'Resources': r, 'Outputs': {'Bucket': {'Value': ref('Files')}, 'ScanPlanArn': {'Value': arn('ScanPlan')}, 'DeadLetters': {'Value': ref('DeadLetters')}}}
